// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Assume caller is not address(0) to avoid zero-address edge cases
        vm.assume(caller != address(0));
        // Bound deposit and collect amounts to reasonable ranges (avoid overflow)
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 0, type(uint128).max);

        // Initialize the contract (one-time setup)
        c.SetMinSum(1 ether); // Arbitrary MinSum
        c.Initialized();

        // Fund the caller with Ether and deposit into contract
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Attempt Collect with the given amount
        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record balance after Collect
        uint256 balanceAfter = c.balances(caller);

        // If the call reverted (e.g., due to insufficient balance), then nothing should change
        if (!success) {
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert");
        } else {
            // If successful, balance must decrease by exactly collectAmount
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance decreased by collectAmount");
        }
    }
}

