pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 balance, uint256 minSum, uint256 am, uint256 depositAmount) public {
        // Bound inputs to avoid overflow/revert
        am = bound(am, 0, 1e30);
        balance = bound(balance, 0, 1e30);
        minSum = bound(minSum, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e30);

        // Ensure the caller has enough ether for deposit
        vm.deal(caller, depositAmount);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit to set the caller's balance
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Now call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        uint256 balanceAfter = c.balances(caller);

        // Rule: If the call reverted (due to failed transfer or other), balance unchanged
        // Otherwise, deduction should only happen if both conditions (balance >= minSum and balance >= am) hold
        if (!success) {
            assertTrue(balanceBefore == balanceAfter);
        } else {
            // If Collect succeeded, the amount was deducted
            // The reference requires both conditions, so we assert that the deduction equals am
            assertTrue(balanceBefore - balanceAfter == am);
        }
    }
}

