pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor1, address actor2, uint256 minSum, uint256 depositAmount1, uint256 depositAmount2, uint256 collectAmount) public {
        // Ensure distinct addresses for meaningful cross-account checks
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);

        // Initialize MinSum
        c.SetMinSum(bound(minSum, 1, 1e18));
        c.Initialized();

        // Fund actor1 with enough to possibly meet MinSum
        vm.deal(actor1, depositAmount1);
        vm.prank(actor1);
        c.Deposit{value: bound(depositAmount1, 1, 1e18)}();

        // Fund actor2 with some balance that won't trigger the condition
        vm.deal(actor2, depositAmount2);
        vm.prank(actor2);
        c.Deposit{value: bound(depositAmount2, 0, minSum - 1)}();

        // Capture balances before collect
        uint256 bal1Before = c.balances(actor1);
        uint256 bal2Before = c.balances(actor2);

        // Attempt collect from actor2 with amount that would be valid if MinSum were not checked
        vm.prank(actor2);
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, bound(collectAmount, 1, bal2Before)));

        // The rule: if actor1's balance decreased (excluding the caller), then the call must have succeeded and both conditions held.
        // Since actor1 is not the caller, its balance should never decrease.
        uint256 bal1After = c.balances(actor1);
        assertTrue(bal1After >= bal1Before);
    }
}

