pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 deposit, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(deposit <= type(uint256).max - 1);
        vm.assume(amount <= type(uint256).max - 1);

        // Setup: initialize and set MinSum
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit funds into caller's account
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        address[] memory addresses = new address[](2);
        addresses[0] = caller;
        addresses[1] = address(0x1234);

        // Record balances before Collect
        uint256[] memory before = new uint256[](2);
        for (uint256 i = 0; i < 2; i++) {
            before[i] = c.balances(addresses[i]);
        }

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", amount));

        // Verify the invariant: for any address k, c.balances(k) >= original balance[k] - amount (if caller was the one affected)
        bool invariantHolds = true;
        for (uint256 i = 0; i < 2; i++) {
            address k = addresses[i];
            uint256 after = c.balances(k);
            if (k == caller && success && c.balances(caller) >= amount) {
                // If caller satisfies condition (including MinSum in reference), balance should decrease by exactly amount
                // But we only check that it doesn't decrease by more than amount
                invariantHolds = invariantHolds && (after >= before[i] - amount);
            } else {
                // Otherwise balance should not decrease
                invariantHolds = invariantHolds && (after >= before[i]);
            }
        }

        assertTrue(invariantHolds, "Invariant violated");
    }
}

