pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Bound deposit and collect amounts to avoid overflow and ensure sensible values
        vm.assume(depositAmount > 0 && depositAmount <= 1e18);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Initialize the contract with MinSum = 0 (so any deposit meets minimum)
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead)); // dummy log address to avoid revert on log call? No, log calls may revert; we handle with try/catch
        c.Initialized();

        // Fund caller
        vm.deal(caller, depositAmount);

        // Deposit
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Try to Collect; it might revert if the call to Log fails (but we don't care about revert differences)
        try c.Collect(collectAmount) {} catch {}

        // Assert: balance after Collect is <= balance before Collect
        uint256 balanceAfter = c.balances(caller);
        assertTrue(balanceAfter <= balanceBefore, "Balance should not increase after Collect");
    }
}

