pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 deposit, uint256 withdraw) public {
        // Bound inputs to avoid overflows and ensure meaningful state
        minSum = bound(minSum, 0, 1e30);
        deposit = bound(deposit, 0, 1e30);
        withdraw = bound(withdraw, 0, 1e30);

        // Set minSum directly (requires not initialized)
        c.SetMinSum(minSum);
        // Set a dummy log address (must be non-zero to avoid revert, but we don't care about logs)
        c.SetLogFile(address(0));
        // Initialize (lock configuration)
        c.Initialized();

        // Fund the caller with enough ether for deposit and gas
        vm.deal(caller, deposit + 1 ether);

        // Deposit to set a balance
        vm.prank(caller);
        (bool depOk, ) = address(c).call{value: deposit}("");
        if (!depOk) { return; } // skip if deposit fails (shouldn't)

        // Compute total supply before Collect: sum of all balances + contract balance
        uint256 totalBefore = c.balances(caller);
        // Note: we only track the caller's balance; we assume no other users.
        // For a general rule, we'd need to iterate over all addresses, but in fuzz we can't.
        // Instead, we consider the simplest case: only caller has balance.
        totalBefore += address(c).balance;

        // Attempt collect
        vm.prank(caller);
        bool collectOk;
        {
            bytes memory data = abi.encodeWithSelector(c.Collect.selector, withdraw);
            (collectOk, ) = address(c).call(data);
        }

        // Compute total after
        uint256 totalAfter = c.balances(caller) + address(c).balance;

        // General rule: total should be invariant regardless of Collect outcome
        // (if it reverted, state unchanged, so invariant holds; if succeeded, still holds)
        assertTrue(totalBefore == totalAfter, "Total supply changed after Collect");
    }
}

