pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        // Bound deposit to avoid overflow; collectAmount must be <= balance after deposit
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract with MinSum = 0
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund sender
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Record balance after deposit
        uint256 balanceAfterDeposit = c.balances(sender);

        // Now call Collect; if balance >= MinSum and >= collectAmount, it will try to subtract
        vm.prank(sender);
        c.Collect(collectAmount);

        // The invariant: after any sequence ending in Collect, the sender's balance should never be less than 0 (trivially)
        // But more precisely, the bug makes balance decrease by deposit (due to subtraction) instead of increase.
        // So the correct balance after deposit should be depositAmount, and after Collect should be depositAmount - collectAmount.
        // The bug: balance after deposit becomes 0, so after Collect it remains 0 (or revert if collectAmount > 0).
        // We assert that the balance after all operations is at least as large as if deposit had increased the balance.
        // Since bug subtracts, the balance is less than expected.
        assertTrue(c.balances(sender) <= balanceAfterDeposit);
    }
}

