pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 deposit, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        vm.assume(deposit <= 1e18);
        vm.assume(collectAmt <= 1e18);
        vm.assume(minSum <= 1e18);
        // Initialize contract
        c.SetMinSum(minSum);
        c.Initialized();
        // Deposit from caller
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();
        // Record state before Collect
        uint256 balBefore = c.balances(caller);
        uint256 contractBalBefore = address(c).balance;
        // Call Collect if balance >= minSum and balance >= collectAmt, else it reverts
        bool willRevert = (balBefore < minSum || balBefore < collectAmt);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        // Check the invariant: when Collect succeeds, the caller's balance decreases by collectAmt
        // and the contract's ether balance decreases by collectAmt (since it sends ether to caller).
        if (!willRevert && success) {
            uint256 balAfter = c.balances(caller);
            uint256 contractBalAfter = address(c).balance;
            // Caller's balance should decrease by exactly collectAmt
            assertTrue(balBefore - balAfter == collectAmt, "Caller balance delta incorrect");
            // Contract's ether balance should decrease by exactly collectAmt
            assertTrue(contractBalBefore - contractBalAfter == collectAmt, "Contract ether balance delta incorrect");
        }
    }
}

