        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Check that the call reverted only if condition didn't hold
        // condition: caller balance >= minSum && caller balance >= collectAmount
        // After deposit, caller's balance in contract = depositAmount
        bool conditionHolds = (depositAmount >= minSum && depositAmount >= collectAmount);
